DO $$ BEGIN IF EXISTS(SELECT 1 FROM work_calendar_holidays) OR EXISTS(SELECT 1 FROM projects WHERE actual_end_date IS NOT NULL OR schedule_calculation IS NOT NULL) THEN RAISE EXCEPTION 'Cannot discard populated calendar or project calculations'; END IF; END $$;
ALTER TABLE projects DROP COLUMN actual_end_date,DROP COLUMN schedule_calculation;DROP TABLE work_calendar_changes;DROP TABLE project_schedule_changes;DROP FUNCTION reject_calendar_history_change();DROP TABLE work_calendar_holidays;
ALTER TABLE projects DROP CONSTRAINT project_capture_bounds;ALTER TABLE projects ADD CONSTRAINT project_capture_bounds CHECK ((contract_value IS NULL OR contract_value>=0) AND (planned_duration_days IS NULL OR planned_duration_days BETWEEN 1 AND 36500) AND (safety_buffer_percent IS NULL OR safety_buffer_percent BETWEEN 0 AND 100) AND (safety_buffer_days IS NULL OR safety_buffer_days BETWEEN 0 AND 36500));
